#!/usr/bin/env bash
# First run, end to end: bring the stack up, upload a generated video through the real path
# (presigned PUT → MinIO webhook → Redis queue → worker → HMAC webhook) and print the player URL.
#
# Needs only docker (with compose), curl and jq on the host — the test video is generated by the
# worker's own FFmpeg. Safe to rerun: the demo user and channel are reused.
#
# Demo login (also printed at the end), for signing in at http://localhost:3000:
#   email    demo@example.com
#   password demo-password
# The video is Public, so the player URL works without signing in.
set -euo pipefail

API=http://localhost:5000
FRONT=http://localhost:3000
USERNAME=demo
EMAIL=demo@example.com
PASSWORD=demo-password
HANDLE=demo-channel
READY_TIMEOUT_SECONDS=300

step() { printf '\n==> %s\n' "$*"; }
fail() {
  printf '\nFAILED: %s\n' "$*" >&2
  docker compose logs --tail=50 minio-init api worker >&2 || true
  exit 1
}

for tool in docker curl jq; do
  command -v "$tool" >/dev/null || { echo "missing: $tool" >&2; exit 1; }
done

cd "$(dirname "$0")/.."

step "Starting the stack (first build takes a few minutes)"
docker compose up -d --build

# minio-init creates the bucket and the upload notification, and restarts MinIO to do it — an
# upload before it exits either fails or never reaches the API. It also starts only once the API
# is healthy, so this one wait covers both.
step "Waiting for minio-init and the API"
docker compose wait minio-init >/dev/null || fail "minio-init failed"

step "Signing in as $EMAIL"
# 409 on a rerun: the user already exists.
curl -sS -o /dev/null -X POST "$API/v1/auth/signup" -H 'Content-Type: application/json' \
  -d "{\"username\":\"$USERNAME\",\"email\":\"$EMAIL\",\"password\":\"$PASSWORD\"}"
access_token=$(curl -fsS -X POST "$API/v1/auth/signin" -H 'Content-Type: application/json' \
  -d "{\"email\":\"$EMAIL\",\"password\":\"$PASSWORD\"}" | jq -r '.data.accessToken')
auth="Authorization: Bearer $access_token"
# 409 on a rerun: the channel already exists.
curl -sS -o /dev/null -X POST "$API/v1/channels" -H 'Content-Type: application/json' -H "$auth" \
  -d "{\"handle\":\"$HANDLE\",\"name\":\"Demo channel\"}"

video_status() {
  curl -fsS "$API/v1/videos/$1" -H "$auth" | jq -r '.data.status.value'
}

step "Creating the video"
created=$(curl -fsS -X POST "$API/v1/users/$USERNAME/channels/$HANDLE/videos" \
  -H 'Content-Type: application/json' -H "$auth" \
  -d '{"title":"Demo video","description":"Generated by make demo","tags":["demo"],"visibility":0}')
video_id=$(jq -r '.data.videoId' <<<"$created")
upload_url=$(jq -r '.data.uploadUrl' <<<"$created")
status=$(video_status "$video_id")
echo "$video_id: $status"
[[ "$status" == PendingUpload ]] || fail "expected PendingUpload, got $status"

step "Generating a 10s test video with the worker's FFmpeg"
video_file=$(mktemp)
trap 'rm -f "$video_file"' EXIT
# Same pattern as GenerateTestVideo in the worker's tests: testsrc 640x480 + sine, H.264 + AAC.
docker compose exec -T worker sh -c '
  out=$(mktemp) &&
  ffmpeg -loglevel error -f lavfi -i testsrc=duration=10:size=640x480:rate=30 \
    -f lavfi -i sine=frequency=1000:duration=10 \
    -pix_fmt yuv420p -c:v libx264 -c:a aac -f mp4 -y "$out" &&
  cat "$out"; rm -f "$out"' >"$video_file"
[[ -s "$video_file" ]] || fail "FFmpeg produced no video"

step "Uploading straight to MinIO (presigned PUT)"
curl -fsS -X PUT -H 'Content-Type: video/mp4' --data-binary "@$video_file" "$upload_url"

step "Waiting for Ready (MinIO webhook → Redis → worker → HMAC webhook)"
deadline=$((SECONDS + READY_TIMEOUT_SECONDS))
last_status=$status
while ((SECONDS < deadline)); do
  status=$(video_status "$video_id")
  [[ "$status" != "$last_status" ]] && echo "$last_status → $status" && last_status=$status
  [[ "$status" == Ready ]] && break
  [[ "$status" == Failed ]] && fail "video $video_id is Failed"
  sleep 0.5
done
[[ "$status" == Ready ]] || fail "video $video_id still $status after ${READY_TIMEOUT_SECONDS}s"

video_url=$(curl -fsS "$API/v1/videos/$video_id" -H "$auth" | jq -r '.data.videoUrl')
[[ "$video_url" != null ]] || fail "Ready without a videoUrl"
curl -fsS -o /dev/null "$FRONT/watch/$video_id" || fail "player page did not load"

cat <<EOF

Ready. Watch it:  $FRONT/watch/$video_id

Sign in at $FRONT with $EMAIL / $PASSWORD
Grafana  http://localhost:3001  (admin/admin)
MinIO    http://localhost:9001  (minioadmin/minioadmin)
EOF
